using System.Windows; using System.Windows.Controls; using FFPerformanceEngine.Core.Models; namespace FFPerformanceEngine.App.Pages; public partial class OptimizePage:UserControl{private AutoTunerMode _mode;private IReadOnlyList<TuningCandidate> _candidates=Array.Empty<TuningCandidate>();public OptimizePage(){InitializeComponent();_mode=App.Services.Settings.KeepDeepAsDefault?AutoTunerMode.Deep:App.Services.Settings.DefaultTunerMode;Loaded+=(_,_)=>Refresh();}private void Adaptive_Click(object s,System.Windows.Input.MouseButtonEventArgs e){_mode=AutoTunerMode.Adaptive;Refresh();}private void Deep_Click(object s,System.Windows.Input.MouseButtonEventArgs e){_mode=AutoTunerMode.Deep;Refresh();}private void Refresh(){var env=App.Services.Environment.Capture();var instance=env.Instances.FirstOrDefault();ModeText.Text=$"Modo: {_mode}";EnvironmentText.Text=env.BlueStacksDetected?$"BlueStacks detectado · {instance?.Name??"instância não identificada"}":"BlueStacks não detectado";_candidates=App.Services.AutoTuner.GenerateCandidates(env,instance,_mode);CandidateText.Text=$"{_candidates.Count} candidatos seguros gerados para exploração.";}private void Generate_Click(object s,RoutedEventArgs e){Refresh();ResultText.Text=$"Gerados {_candidates.Count} candidatos. Nenhum vencedor será escolhido antes de benchmark real.";Progress.Value=15;}private async void Capture_Click(object s,RoutedEventArgs e){Progress.IsIndeterminate=true;ResultText.Text="Capturando 12 segundos de frame telemetry via PresentMon...";var sample=await App.Services.PresentMon.CaptureAsync(TimeSpan.FromSeconds(12));Progress.IsIndeterminate=false;if(sample is null){ResultText.Text=App.Services.PresentMon.FindExecutable() is null?"PresentMon não está instalado. Execute scripts/Get-PresentMon.ps1 e tente novamente.":"Não foi possível medir frames. Inicie uma instância BlueStacks ativa e tente novamente.";Progress.Value=0;return;}ResultText.Text=$"FPS {sample.Fps:0.0} · 1% Low {sample.OnePercentLow:0.0} · Frame Time {sample.FrameTimeMs:0.00} ms · Latência {(sample.LatencyMs?.ToString("0.0")??"—")} ms. Evidência registrada; execute candidatos adicionais para comparar.";Progress.Value=100;await App.Services.History.AppendAsync(new HistoryEvent{Kind=HistoryEventKind.Benchmark,Title="Benchmark real",Summary=ResultText.Text});}}